import{_ as r,C as o,o as a,c as i,ag as s,E as n}from"./chunks/framework.cyF4XceO.js";const b=JSON.parse('{"title":"Ownership","description":"The repositories and runtimes that own each Takoform boundary.","frontmatter":{"title":"Ownership","description":"The repositories and runtimes that own each Takoform boundary."},"headers":[],"relativePath":"docs/ownership.md","filePath":"docs/ownership.md"}'),c={name:"docs/ownership.md"};function d(h,e,l,p,m,u){const t=o("StatusNote");return a(),i("div",null,[e[0]||(e[0]=s('<h1 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h1><p>Takoform stays portable because each boundary has one authority. A Provider can project a contract, but it cannot become the authority for the contract it consumes.</p><table tabindex="0"><thead><tr><th>Boundary</th><th>Owner</th><th>What that owner decides</th></tr></thead><tbody><tr><td>Normative Specification, schemas, conformance, receipts</td><td><a href="https://github.com/tako0614/takoform" target="_blank" rel="noreferrer"><code>takoform</code></a></td><td>Host API semantics, identity grammar, canonicalization, package/trust format, and historical evidence. The same repository publishes Core <code>v1.1.0</code>.</td></tr><tr><td>Form families and exact FormRefs</td><td><a href="https://github.com/tako0614/takoform-forms" target="_blank" rel="noreferrer"><code>takoform-forms</code></a></td><td>Family groups, <code>formId</code>, <code>definitionVersion</code>, Form/package bytes, fixtures, signatures, deprecation, and revocation.</td></tr><tr><td>Terraform/OpenTofu Provider</td><td><a href="https://github.com/tako0614/terraform-provider-takoform" target="_blank" rel="noreferrer"><code>terraform-provider-takoform</code></a></td><td>Typed resource/state/import mappings and immutable Provider release history.</td></tr><tr><td>Host runtime</td><td>The host operator and implementation</td><td>Capability support, placement, scaling, credentials, routing, recovery, billing, quota, SLA, and live catalog.</td></tr><tr><td>Deployment and secrets</td><td>The operator</td><td>Endpoint, space, credentials, capacity policy, and production state. These never become public Form or Provider metadata.</td></tr></tbody></table><h2 id="practical-consequences" tabindex="-1">Practical consequences <a class="header-anchor" href="#practical-consequences" aria-label="Permalink to &quot;Practical consequences&quot;">​</a></h2><ul><li>A Provider release does not publish a Form or change the Host API lane.</li><li>A Core release does not select a Provider version or promote a Form.</li><li>A Form publisher changes <code>definitionVersion</code> when the Form&#39;s semantics change.</li><li>A host advertises the exact FormRefs it supports through its Host Support Profile.</li><li>The site can summarize these facts, but it does not own live capability, credentials, or deployment state.</li></ul><p>The current wire identity is the literal <code>forms.takoform.com/v1</code>. The site does not mint <code>/v1.1</code> or treat a numbered Specification receipt as a release authority for the other owners.</p><h2 id="source-and-history" tabindex="-1">Source and history <a class="header-anchor" href="#source-and-history" aria-label="Permalink to &quot;Source and history&quot;">​</a></h2><p>The <a href="/docs/versions.html">version model</a> shows the four current streams. The retained <a href="/spec/">Specification routes</a> and <a href="/release/">release routes</a> are historical source; their banners make that status explicit.</p>',8)),n(t)])}const y=r(c,[["render",d]]);export{b as __pageData,y as default};
